UPDATE tasks
SET research_trends = jsonb_build_array(
    '**Driving stacks are collapsing around planning.** The frontier is moving beyond loosely coupled perception, prediction, and control toward end-to-end systems whose shared representations are optimized for the trajectory itself. [UniAD](/paper/2212.10156) unified full-stack tasks through planning queries, [VAD](/paper/2303.12077) replaced dense rasters with efficient vectorized scene constraints, and [Drive-JEPA](/paper/2601.22032) now couples self-supervised video representations with proposal-centric trajectory distillation.',
    '**World models are becoming both teachers and testbeds.** Recent work learns future scene features, synthesizes counterfactual observations, and trains on rare states that logged human driving misses. [LAW](/paper/2406.08481) adds latent feature prediction, [SimScale](/paper/2511.23369) co-trains on reactively rendered scenarios with pseudo-expert trajectories, while [Pseudo-Simulation](/paper/2506.04218) extends evaluation toward error recovery between cheap open-loop scoring and expensive closed-loop simulation.',
    '**Imitation learning is giving way to reasoning and corrective supervision.** Driving VLMs reserve language for high-level decisions while trajectory heads retain control, then add QA pretraining, reinforcement learning, reflection, or expert–student alignment for long-tail safety. [Senna](/paper/2410.22313) established the split planner; [ReCogDrive](/paper/2506.08052), [ReflectDrive](/paper/2509.20109), and [LEAD](/paper/2512.20563) show the move toward simulator feedback, self-correction, and reduced privileged-expert asymmetry on [NAVSIM v1](/benchmark/navsim-v1?task=autonomous-driving) and [Bench2Drive](/benchmark/bench2drive-v0-0-3?task=autonomous-driving).'
),
updated_at = NOW()
WHERE slug = 'autonomous-driving';
